export async function compileMd2Runtime(options = {}) {
  return md2.compileMd2App({
    files: normalizeFiles(options.files || {}),
    entry: options.entry || 'index.html'
  });
}

export function runMd2Runtime(bytecode, options = {}) {
  const run = md2.runMd2App(bytecode, options);
  return { ...run, result: summarizeMd2Run(run) };
}

export async function simulateMd2Runtime(options = {}) {
  const compiled = await compileMd2Runtime(options);
  const run = runMd2Runtime(compiled.bytecode, options.runOptions || options);
  return {
    BH: 'B"H',
    ok: run.ok !== false,
    runtime: options.runtime || 'browser',
    engine: 'md2',
    entry: options.entry || 'index.html',
    bytecode: {
      kind: compiled.kind,
      magic: compiled.magic,
      bytes: compiled.bytecode.length,
      base64: compiled.bytecode64
    },
    result: run.result,
    score: run.ok === false ? 0 : 100,
    suggestions: []
  };
}

export async function compileAndRunMd2Js(source = '', options = {}) {
  return md2.compileAndRunMd2Js(source, options);
}

export function inspectMd2(bytecode) {
  return md2.inspectMd2(bytecode);
