//B"H
import { StreamRouter } from "../../app/streamRouter.js";
import { parseStreamChunk } from "./workerStreamClient.js";
import { streamResumeStore } from "./streamResumeStore.js";

const activeResumes = new Set();

/**
 * B"H — Reattaches a refreshed page to background-owned streams.
 *
 * On refresh, the extension-injected fetch bridge can arrive after this module
 * is called, and early stream packets may not yet contain a conversation id.
 * This resumer therefore waits briefly for a resume-capable bridge and permits
 * ownerless stream entries to reattach to the currently visible chat instead of
 * silently abandoning them.
