function askWorker(message) {
  if (pending.size > MAX_PENDING) resetWorker("too many pending render-worker replies");
  if (!worker) worker = makeWorker();
  if (!worker) return Promise.resolve({});
  const id = ++seq;
  return new Promise(resolve => {
