    status.textContent = "Synthesizing audio…";
    const service = await aiHandler?.getActiveService?.();
    const result = await service?.getAwtsmoosAudio?.({ message_id: messageId, conversation_id: conversationId, voice: settings.voice, format: settings.format, download: false });
    if (!result?.url) throw new Error("No audio URL returned.");
    const wrap = root.querySelector(".audio-player-wrap");
