        stream.waiters.push(finish);
        if (timeoutMs > 0) timer = setTimeout(finish, timeoutMs);
      });
    }

    wake(stream) {
      const waiters = stream.waiters.splice(0);
      for (const resolve of waiters) resolve();
    }

