/* B"H */
#include <windows.h>
#include <gl/gl.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>

#ifndef AWTS_MERKAVA_REPORT_JSON
#define AWTS_MERKAVA_REPORT_JSON "{\"BH\":\"B'H\",\"warning\":\"native report header missing\"}"
#endif

static int g_running = 1;
static int g_frames = 0;
static unsigned int g_bytecode_len = 0;
static unsigned int g_bytecode_ok = 0;
static unsigned int g_section = 0;
static unsigned int g_version = 0;

static LRESULT CALLBACK AwtsWndProc(HWND hwnd, UINT msg, WPARAM wp, LPARAM lp) {
  switch (msg) {
    case WM_CLOSE:
    case WM_DESTROY:
      g_running = 0;
      PostQuitMessage(0);
      return 0;
  }
  return DefWindowProc(hwnd, msg, wp, lp);
}

static int load_merkava_file(const char* path) {
  FILE* f = fopen(path, "rb");
  if (!f) return 0;
  unsigned char head[8] = {0,0,0,0,0,0,0,0};
  fseek(f, 0, SEEK_END);
  long size = ftell(f);
  fseek(f, 0, SEEK_SET);
  fread(head, 1, 8, f);
  fclose(f);
  g_bytecode_len = size > 0 ? (unsigned int)size : 0;
  g_bytecode_ok = (size >= 5 && head[0] == 'M' && head[1] == 'D' && head[2] == '2' && head[3] == 0);
  g_section = head[4];
  g_version = head[5];
  return g_bytecode_ok ? 1 : 0;
}

static void print_runtime_report(void) {
  printf("---- embedded Merkava runtime report ----\n");
  printf("%s\n", AWTS_MERKAVA_REPORT_JSON);
  printf("---- native capabilities ----\n");
  printf("dom=planned-native-tree webgl=win32-opengl-bridge console=stdout bytecode-loader=fs\n");
  printf("js-understanding=MerkavaASTParser+MerkavaBytecodeApi build-time report embedded\n");
  printf("html-css-js=compiled-to-merkava-bytecode source-map=report-json\n");
}

static void draw_scene(void) {
  float pulse = (float)((g_frames % 120) / 120.0f);
  glViewport(0, 0, 960, 540);
  glClearColor(0.015f, 0.02f + pulse * 0.05f, 0.04f, 1.0f);
  glClear(GL_COLOR_BUFFER_BIT);

  glBegin(GL_TRIANGLES);
    glColor3f(1.0f, 0.25f, 0.15f); glVertex2f(-0.72f, -0.55f);
    glColor3f(0.1f, 0.9f, 0.35f);  glVertex2f( 0.72f, -0.55f);
    glColor3f(0.25f, 0.45f, 1.0f); glVertex2f( 0.00f,  0.72f);
  glEnd();

  glBegin(GL_LINE_LOOP);
    glColor3f(0.95f, 0.95f, 1.0f); glVertex2f(-0.86f, -0.78f);
    glColor3f(0.95f, 0.95f, 1.0f); glVertex2f( 0.86f, -0.78f);
    glColor3f(0.95f, 0.95f, 1.0f); glVertex2f( 0.86f,  0.78f);
    glColor3f(0.95f, 0.95f, 1.0f); glVertex2f(-0.86f,  0.78f);
  glEnd();
}

int main(int argc, char** argv) {
  const char* bytecodePath = argc > 1 ? argv[1] : "sample.merkava";
  int loaded = load_merkava_file(bytecodePath);

  printf("B'H Merkava Native Browser / Runtime Executor\n");
  printf("bytecode=%s bytes=%u ok=%u section=%u version=%u\n", bytecodePath, g_bytecode_len, g_bytecode_ok, g_section, g_version);
  print_runtime_report();
  fflush(stdout);

  HINSTANCE hInst = GetModuleHandle(NULL);
  WNDCLASS wc;
  ZeroMemory(&wc, sizeof(wc));
  wc.style = CS_OWNDC;
  wc.lpfnWndProc = AwtsWndProc;
  wc.hInstance = hInst;
  wc.lpszClassName = "AwtsMerkavaNativeBrowser";
  wc.hCursor = LoadCursor(NULL, IDC_ARROW);
  if (!RegisterClass(&wc)) {
    printf("register_window_failed=%lu\n", GetLastError());
    return 10;
  }

  HWND hwnd = CreateWindowEx(
    0, wc.lpszClassName, "B'H Merkava Native Browser - OpenGL/WebGL Bridge",
    WS_OVERLAPPEDWINDOW | WS_VISIBLE,
    CW_USEDEFAULT, CW_USEDEFAULT, 960, 540,
    NULL, NULL, hInst, NULL
  );
  if (!hwnd) {
    printf("create_window_failed=%lu\n", GetLastError());
    return 11;
  }

  HDC dc = GetDC(hwnd);
  PIXELFORMATDESCRIPTOR pfd;
  ZeroMemory(&pfd, sizeof(pfd));
  pfd.nSize = sizeof(pfd);
  pfd.nVersion = 1;
  pfd.dwFlags = PFD_DRAW_TO_WINDOW | PFD_SUPPORT_OPENGL | PFD_DOUBLEBUFFER;
  pfd.iPixelType = PFD_TYPE_RGBA;
  pfd.cColorBits = 32;
  pfd.cDepthBits = 24;
  pfd.iLayerType = PFD_MAIN_PLANE;
  int pf = ChoosePixelFormat(dc, &pfd);
  if (!pf || !SetPixelFormat(dc, pf, &pfd)) {
    printf("pixel_format_failed=%lu\n", GetLastError());
    return 12;
  }

  HGLRC rc = wglCreateContext(dc);
  if (!rc || !wglMakeCurrent(dc, rc)) {
    printf("opengl_context_failed=%lu\n", GetLastError());
    return 13;
  }

  printf("opengl_vendor=%s\n", glGetString(GL_VENDOR));
  printf("opengl_renderer=%s\n", glGetString(GL_RENDERER));
  printf("opengl_version=%s\n", glGetString(GL_VERSION));
  fflush(stdout);

  MSG msg;
  DWORD start = GetTickCount();
  while (g_running && GetTickCount() - start < 2200) {
    while (PeekMessage(&msg, NULL, 0, 0, PM_REMOVE)) {
      if (msg.message == WM_QUIT) g_running = 0;
      TranslateMessage(&msg);
      DispatchMessage(&msg);
    }
    draw_scene();
    SwapBuffers(dc);
    g_frames++;
    Sleep(16);
  }

  wglMakeCurrent(NULL, NULL);
  if (rc) wglDeleteContext(rc);
  ReleaseDC(hwnd, dc);
  DestroyWindow(hwnd);
  printf("frames=%d loaded=%d renderer=win32-opengl status=complete\n", g_frames, loaded);
  fflush(stdout);
  return loaded ? 0 : 2;
}

