  long size = ftell(f);
  fseek(f, 0, SEEK_SET);
  fread(head, 1, 8, f);
  fclose(f);
  state->bytecodeLen = size > 0 ? (unsigned int)size : 0;
  state->bytecodeOk = (size >= 5 && head[0] == 'M' && head[1] == 'D' && head[2] == '2' && head[3] == 0);
  state->section = head[4];
  state->version = head[5];
  state->loaded = state->bytecodeOk ? 1 : 0;
  return state->loaded;
}

