  let node = mapping[convo.current_node];
  while (node && !seen.has(node.id)) {
    seen.add(node.id);
    ordered.push(node);
    node = mapping[node.parent];
  }
  return ordered.reverse().map((item, index) => stampHistoryOrder(item, index));
