function escapeText(text) { return String(text || "").replace(/[&<>]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c])); }
function escapeAttr(text) { return escapeText(text).replace(/"/g, "&quot;"); }

