void awts_resolve_exe_relative_path(const char* name, char* out, size_t cap) {
  char exe[MAX_PATH];
  DWORD n = GetModuleFileNameA(NULL, exe, MAX_PATH);
  if (!n || n >= MAX_PATH) {
    snprintf(out, cap, "%s", name);
    return;
  }
  char* slash = strrchr(exe, '\\');
  if (slash) slash[1] = 0;
  snprintf(out, cap, "%s%s", exe, name);
}

