static void draw_address(AwtsBrowserState* state) {
  float ax = sx(state, 170), ay = sy(state, 64), aw = sw(state, state->width - 230), ah = -sh(state, 28);
  rect(ax, ay, aw, ah, state->hoverAddress ? 0.98f : 0.96f, 0.98f, 1.0f);
