  rect(sx(state, 62), sy(state, 45), sw(state, 38), -sh(state, 28), 0.95f, 0.72f, 0.18f);
  rect(sx(state, 108), sy(state, 45), sw(state, 38), -sh(state, 28), 0.18f, 0.78f, 0.34f);
