/**
 * Emulates an EXE at a high semantic layer: headers, sections, subsystem, host calls.
 * It does not execute arbitrary machine code; it safely interprets PE intent.
 * @param {{subsystem:string, entryRva:number, imageBase:number, sections:Array}} pe parsed PE
 * @param {{print:Function, openWindow:Function}} win virtual Windows host
 * @returns {{mode:string, message:string}}
 */
export function emulatePortableExecutable(pe, win) {
  win.print('Awtsmoos loader: MZ became PE, PE became mapped memory.');
  win.print(`ImageBase: 0x${pe.imageBase.toString(16)}`);
  win.print(`EntryRVA: 0x${pe.entryRva.toString(16)}`);
  pe.sections.forEach(sec => win.print(sectionLine(sec)));

  if (pe.subsystem === 'windows-gui') {
    const body = 'A GUI executable was mapped into the virtual desktop.';
    win.openWindow('Virtual MessageBoxA', body);
    return { mode: 'gui', message: body };
  }

  const message = 'Console executable entered the virtual stdout river.';
  win.print(message);
  return { mode: 'console', message };
}

function sectionLine(sec) {
  return `${sec.name || '.section'} RVA=0x${sec.virtualAddress.toString(16)} RAW=${sec.rawSize}`;
}

